# owner: platform
"""Snap span start and end times to a fixed step, for payroll."""

from typing import Iterable, List
from hourglass.parsing import format_span
from hourglass.models import Span

MINUTES_PER_HOUR = 60

# ---
def label_rounded_spans(spans: Iterable[Span], step: int) -> List[str]:
    """Round each span to the nearest step and label it, like 09:00-17:15 (8h 15m)."""
    _check_step(step)
    return [_label_span(_round_span(span, step)) for span in spans]

def _check_step(step: int) -> None:
    valid = isinstance(step, int) and step > 0 and MINUTES_PER_HOUR % step == 0
    if not valid:
        raise ValueError(f"step must divide 60 evenly, got {step!r}")

def _round_minute(minute: int, step: int) -> int:
    # Halves round up, so 09:15 with a 30 minute step becomes 09:30.
    return (minute + step // 2) // step * step

def _round_span(span: Span, step: int) -> Span:
    start = _round_minute(span.start, step)
    end = _round_minute(span.end, step)
    if start == end:
        raise ValueError(f"span {format_span(span)} rounds to nothing at step {step}")
    return Span(start, end)

def _label_span(span: Span) -> str:
    hours, minutes = divmod(span.minutes, MINUTES_PER_HOUR)
    return f"{format_span(span)} ({hours}h {minutes}m)"

