# owner: platform
import unittest

from hourglass.rounding import label_rounded_spans
from hourglass.models import Span

class LabelTests(unittest.TestCase):
    def test_exact_times_are_unchanged(self):
        labels = label_rounded_spans([Span(540, 1020)], 15)
        self.assertEqual(labels, ["09:00-17:00 (8h 0m)"])

    def test_rounds_to_nearest_step(self):
        labels = label_rounded_spans([Span(541, 1034)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        labels = label_rounded_spans([Span(555, 1065)], 30)
        self.assertEqual(labels, ["09:30-18:00 (8h 30m)"])

    def test_keeps_order_of_spans(self):
        spans = [Span(600, 720), Span(540, 600)]
        self.assertEqual(
            label_rounded_spans(spans, 60),
            ["10:00-12:00 (2h 0m)", "09:00-10:00 (1h 0m)"]
        )

    def test_end_of_day_is_allowed(self):
        labels = label_rounded_spans([Span(1400, 1440)], 60)
        self.assertEqual(labels, ["23:00-24:00 (1h 0m)"])

    def test_empty_list(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_span_rounding_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([Span(1436, 1439)], 15)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 90, 7.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans([Span(540, 1020)], step)

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([], 7)

    def test_steps_that_divide_an_hour_are_accepted(self):
        for step in (1, 2, 5, 10, 12, 20, 60):
            with self.subTest(step=step):
                self.assertEqual(len(label_rounded_spans([Span(540, 1020)], step)), 1)
